const DriverPage=(()=>{const $=id=>document.getElementById(id);const esc=s=>escapeHtml(s==null?"":String(s));const rid=()=>"d"+Date.now().toString(36)+Math.random().toString(36).slice(2,10);let home=null;let watchId=null,watchJob="",lastSent=0;const proofs={};const call=(action,payload)=>Api.post(action,Object.assign({token:CustomerAuth.getToken()},payload||{}));async function init(){if(!CustomerAuth.getToken()){show("drv-signin");$("drv-status").textContent="";return}$("drv-apply-form").addEventListener("submit",onApply);$("drv-online").addEventListener("click",onToggleOnline);document.addEventListener("click",onClick);document.addEventListener("change",onChange);await load();setInterval(()=>{if(document.visibilityState==="visible")load()},3e4)}function show(id){["drv-signin","drv-closed","drv-apply","drv-wait","drv-app"].forEach(x=>{$(x).hidden=x!==id})}async function load(){const res=await call("getDriverHome");if(!res.ok){if(res.authRequired){show("drv-signin");$("drv-status").textContent="";return}$("drv-status").textContent=res.error||"Could not load. Check your connection.";return}home=res;$("drv-status").textContent="";const d=res.driver;if(!d){if(!res.enabled){show("drv-closed");return}show("drv-apply");if(!$("drv-vehicle").options.length){$("drv-vehicle").innerHTML=Object.entries(res.vehicles).map(([k,v])=>`<option value="${esc(k)}">${esc(v)}</option>`).join("");$("drv-area").innerHTML=res.areas.map(a=>`<option>${esc(a)}</option>`).join("");const p=CustomerAuth.getCustomer()||{};$("drv-name").value=p.name||"";$("drv-phone").value=p.phone||""}return}if(d.status!=="approved"){show("drv-wait");$("drv-wait-text").textContent=d.status==="pending"?"Thank you - your application is waiting for a Mwakete admin. You will get an email when it is approved.":`Your driver status is: ${d.status}.${d.note?" Reason: "+d.note:""}`;return}show("drv-app");renderOnline(d.available);$("drv-k-active").textContent=res.mine.length;$("drv-k-done").textContent=res.earnings.delivered;$("drv-k-fees").textContent=formatMoney(res.earnings.fees);$("drv-k-paid").textContent=formatMoney(res.earnings.feesPaid);renderMine(res.mine);$("drv-open").innerHTML=!d.available?'<p class="dash-empty">Go online to see available jobs.</p>':res.open.length?res.open.map(j=>`<article class="drv-job">\n          <strong>${esc(j.storeName)}</strong> → ${esc(j.dropoffArea)}<br>\n          <span class="helper-text">${j.items} item(s) · posted ${esc(new Date(j.postedAt).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}))}</span>\n          <p class="drv-fee">Fee ${formatMoney(j.fee)} <span class="helper-text">paid by the seller</span></p>\n          <button type="button" class="btn btn-primary" data-accept="${esc(j.jobId)}" data-version="${j.version}">Accept job</button></article>`).join(""):'<p class="dash-empty">No jobs right now. New jobs appear here (and you get an email).</p>';$("drv-hist").innerHTML=res.history.length?`<table class="dash-table"><thead><tr><th scope="col">Store</th><th scope="col">Result</th><th scope="col">Fee</th></tr></thead><tbody>${res.history.map(j=>`<tr>\n      <td data-label="Store">${esc(j.storeName)}<span class="dash-table-sub">${esc(new Date(j.updatedAt).toLocaleDateString())}</span></td>\n      <td data-label="Result">${esc(j.statusLabel)}${j.failReason?`<span class="dash-table-sub">${esc(j.failReason)}</span>`:""}</td>\n      <td data-label="Fee">${formatMoney(j.fee)}${j.status==="delivered"?`<span class="dash-table-sub">${j.feePaid?"Marked paid":"Not marked paid yet"}</span>`:""}</td></tr>`).join("")}</tbody></table>`:'<p class="dash-empty">No past jobs yet.</p>';if(watchId!==null&&!res.mine.some(j=>j.jobId===watchJob))stopSharing(false)}function renderOnline(on){$("drv-online").setAttribute("aria-checked",on?"true":"false");$("drv-online").classList.toggle("is-open",on);$("drv-online-label").textContent=on?"Online":"Offline";$("drv-online-hint").textContent=on?"You can see and accept new jobs.":"Go online to see new jobs on your island."}function chatHtml(j){const c=j.chat;if(!c)return"";const f=c.fee,id=esc(j.jobId);const state=f.locked?"Agreed and locked":f.agreedByMe&&!f.agreedByOther?"Waiting for the seller to agree":f.canAgree?"The seller proposed this fee":"Not agreed yet";const msgs=c.messages.length?c.messages.map(m=>`<li class="tx-jc-msg tx-jc-${m.by==="system"?"system":m.mine?"mine":"theirs"}">\n        <span class="helper-text">${m.by==="system"?"Mwakete":m.mine?"You":"Seller"}</span><br>${esc(m.body)}</li>`).join(""):'<li class="helper-text">No messages yet. Say hello and agree the fee.</li>';return`<div class="tx-jobchat" role="group" aria-label="Chat with the seller">\n      <p><strong>Delivery fee ${formatMoney(f.amount)}</strong> · <span class="helper-text">${esc(state)}</span></p>\n      ${!f.locked&&j.status==="accepted"?'<p class="helper-text">You can collect the goods once you and the seller have both agreed the fee.</p>':""}\n      ${f.canAgree?`<button type="button" class="btn btn-small btn-primary" data-jc="agree" data-job-id="${id}" data-fee="${esc(f.amount)}">Agree to ${formatMoney(f.amount)}</button>`:""}\n      ${f.canPropose?`<div class="tx-jc-form"><label class="helper-text" for="jcfee-${id}">Propose a different fee ($)</label>\n        <input id="jcfee-${id}" type="number" min="0.5" max="500" step="0.5" inputmode="decimal">\n        <button type="button" class="btn btn-small btn-outline" data-jc="propose" data-job-id="${id}">Propose</button></div>`:""}\n      <ul class="tx-jc-list">${msgs}</ul>\n      ${c.canWrite?`<div class="tx-jc-form"><label class="helper-text" for="jctext-${id}">Message the seller</label>\n        <textarea id="jctext-${id}" rows="2" maxlength="1000" data-chat-input="${id}"></textarea>\n        <button type="button" class="btn btn-small btn-primary" data-jc="message" data-job-id="${id}">Send</button></div>`:""}\n      <p class="form-error" id="jcerr-${id}" role="alert"></p>\n    </div>`}function renderMine(list){const typed={};document.querySelectorAll("[data-chat-input]").forEach(el=>{if(el.value)typed[el.dataset.chatInput]=el.value});$("drv-mine").innerHTML=list.length?list.map(j=>`<article class="drv-job is-mine" data-job="${esc(j.jobId)}">\n      <p><strong>${esc(j.statusLabel)}</strong> · fee ${formatMoney(j.fee)}</p>\n      <dl class="dash-facts">\n        <div><dt>Collect from</dt><dd>${esc(j.storeName)} - ${esc(j.pickup)}${j.storePhone?` · <a href="tel:${esc(j.storePhone)}">${esc(j.storePhone)}</a>`:""}</dd></div>\n        <div><dt>Deliver to</dt><dd>${esc(j.buyerName)}, ${esc(j.dropoff)} · <a href="tel:${esc(j.buyerPhone)}">${esc(j.buyerPhone)}</a> · <a href="${esc(j.mapSearch)}" target="_blank" rel="noopener">Map</a></dd></div>\n        <div><dt>Items</dt><dd>${j.items.map(esc).join(", ")}</dd></div>\n        ${j.notes?`<div><dt>Notes</dt><dd>${esc(j.notes)}</dd></div>`:""}\n      </dl>\n      ${chatHtml(j)}\n      <div class="tx-check"><input type="checkbox" id="share-${esc(j.jobId)}" data-share="${esc(j.jobId)}" ${watchJob===j.jobId?"checked":""}>\n        <label for="share-${esc(j.jobId)}">Share my live location with the buyer and seller for this job (while this page is open)</label></div>\n      <p class="form-error" id="err-${esc(j.jobId)}" role="alert"></p>\n      ${j.status==="accepted"?`<button type="button" class="btn btn-primary" data-act="picked_up" data-job-id="${esc(j.jobId)}">I've collected the goods</button>`:""}\n      ${j.status==="picked_up"?`<div class="drv-deliver">\n          <div class="field"><label for="rcpt-${esc(j.jobId)}">Received by (name)</label><input id="rcpt-${esc(j.jobId)}" maxlength="80"></div>\n          <div class="field"><span class="tx-files-label">Photo of the delivered goods (required)</span>\n            <label class="btn btn-small tx-attach"><span>Take or choose photo</span><input type="file" accept="image/*" capture="environment" class="sr-only" data-proof="${esc(j.jobId)}"></label>\n            <span class="helper-text" id="proof-${esc(j.jobId)}">${proofs[j.jobId]?"Photo saved ✓":""}</span></div>\n          <button type="button" class="btn btn-primary" data-act="delivered" data-job-id="${esc(j.jobId)}">Delivered</button>\n        </div>`:""}\n      <details class="drv-fail"><summary>Couldn't deliver?</summary>\n        <div class="field"><label for="why-${esc(j.jobId)}">What happened</label><select id="why-${esc(j.jobId)}">${Object.entries(home.failReasons).map(([k,v])=>`<option value="${esc(k)}">${esc(v)}</option>`).join("")}</select></div>\n        <div class="field"><label for="note-${esc(j.jobId)}">Note</label><textarea id="note-${esc(j.jobId)}" rows="2" maxlength="300"></textarea></div>\n        <button type="button" class="btn btn-outline" data-act="failed" data-job-id="${esc(j.jobId)}">Report failed delivery</button>\n      </details>\n    </article>`).join(""):'<p class="dash-empty">No active jobs.</p>';document.querySelectorAll("[data-chat-input]").forEach(el=>{if(typed[el.dataset.chatInput])el.value=typed[el.dataset.chatInput]})}async function onChat(btn){const jobId=btn.dataset.jobId,kind=btn.dataset.jc;const err=$("jcerr-"+jobId);err.textContent="";let action,payload;if(kind==="agree"){action="driverAgreeFee";payload={fee:btn.dataset.fee}}else if(kind==="propose"){action="driverProposeFee";payload={fee:$("jcfee-"+jobId).value}}else{action="driverJobMessage";payload={text:$("jctext-"+jobId).value.trim()}}btn.disabled=true;const res=await call(action,Object.assign({jobId:jobId,requestId:rid()},payload));btn.disabled=false;if(!res.ok){err.textContent=res.error||"Not saved - check your connection and try again.";if(res.stale)await load();return}if(kind==="message")$("jctext-"+jobId).value="";await load()}async function onApply(e){e.preventDefault();const err=$("drv-apply-error");err.textContent="";const res=await call("driverApply",{name:$("drv-name").value.trim(),phone:$("drv-phone").value.trim(),vehicle:$("drv-vehicle").value,area:$("drv-area").value,agree:$("drv-agree").checked});if(!res.ok){err.textContent=res.error||"Not sent - try again.";return}await load()}async function onToggleOnline(){const on=$("drv-online").getAttribute("aria-checked")!=="true";$("drv-online").disabled=true;const res=await call("driverSetAvailable",{available:on});$("drv-online").disabled=false;if(!res.ok){$("drv-online-hint").textContent=res.error||"Could not change - try again.";return}await load()}async function onClick(e){const acc=e.target.closest("[data-accept]");if(acc){acc.disabled=true;const res=await call("driverAcceptJob",{jobId:acc.dataset.accept,version:acc.dataset.version,requestId:rid()});if(!res.ok){alert(res.error||"Could not accept - try again.");acc.disabled=false}await load();return}const chat=e.target.closest("[data-jc]");if(chat){await onChat(chat);return}const btn=e.target.closest("[data-act]");if(!btn)return;const jobId=btn.dataset.jobId,act=btn.dataset.act;const payload={jobId:jobId,act:act,requestId:btn.dataset.rid||(btn.dataset.rid=rid())};if(act==="delivered"){payload.recipientName=$("rcpt-"+jobId).value.trim();payload.proofId=proofs[jobId]||""}if(act==="failed"){payload.reason=$("why-"+jobId).value;payload.note=$("note-"+jobId).value.trim()}if(act==="picked_up"&&!confirm("Confirm you have collected the goods from the store?"))return;if(act==="delivered"&&!confirm("Confirm the goods were handed over?"))return;btn.disabled=true;const res=await call("driverUpdateJob",payload);btn.disabled=false;if(!res.ok){$("err-"+jobId).textContent=res.error||"Not saved - check your connection and try again.";return}if(act!=="picked_up"&&watchJob===jobId)stopSharing(false);await load()}async function onChange(e){const share=e.target.closest("[data-share]");if(share){if(share.checked)startSharing(share.dataset.share);else stopSharing(true);return}const proof=e.target.closest("[data-proof]");if(proof&&proof.files&&proof.files[0]){const jobId=proof.dataset.proof;const note=$("proof-"+jobId);note.textContent="Uploading…";try{const{blob:blob,thumb:thumb}=await shrink(proof.files[0]);const res=await call("driverUploadProof",{jobId:jobId,mimeType:"image/jpeg",dataBase64:await toB64(blob),thumbBase64:await toB64(thumb),requestId:rid()});if(!res.ok){note.textContent=res.error||"Upload failed - try again.";return}proofs[jobId]=res.proofId;note.textContent="Photo saved ✓"}catch(err){note.textContent="That photo could not be read - try again."}}}function startSharing(jobId){if(!navigator.geolocation){alert("This phone does not share location from the browser.");return}stopSharing(false);watchJob=jobId;watchId=navigator.geolocation.watchPosition(pos=>{if(Date.now()-lastSent<3e4)return;lastSent=Date.now();call("driverShareLocation",{jobId:jobId,share:true,lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy})},()=>{const box=document.getElementById("share-"+jobId);if(box)box.checked=false;stopSharing(false);alert("Location is blocked on this phone. Allow it in the browser settings to share.")},{enableHighAccuracy:true,maximumAge:2e4,timeout:3e4})}function stopSharing(tellServer){if(watchId!==null&&navigator.geolocation)navigator.geolocation.clearWatch(watchId);if(tellServer&&watchJob)call("driverShareLocation",{jobId:watchJob,share:false});watchId=null;watchJob="";lastSent=0}function toB64(blob){return new Promise((resolve,reject)=>{const r=new FileReader;r.onload=()=>resolve(String(r.result).split(",")[1]||"");r.onerror=reject;r.readAsDataURL(blob)})}function shrink(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file);const img=new Image;img.onload=()=>{URL.revokeObjectURL(url);const draw=(max,q)=>new Promise(res=>{const s=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight));const c=document.createElement("canvas");c.width=Math.max(1,Math.round(img.naturalWidth*s));c.height=Math.max(1,Math.round(img.naturalHeight*s));const x=c.getContext("2d");x.fillStyle="#fff";x.fillRect(0,0,c.width,c.height);x.drawImage(img,0,0,c.width,c.height);c.toBlob(b=>res(b),"image/jpeg",q)});Promise.all([draw(2048,.85),draw(320,.7)]).then(([blob,thumb])=>resolve({blob:blob,thumb:thumb}))};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error("image"))};img.src=url})}return{init:init}})();document.addEventListener("DOMContentLoaded",()=>DriverPage.init());